vec2 hash2(vec2 p ) {
   return fract(sin(vec2(dot(p, vec2(123.4, 748.6)), dot(p, vec2(547.3, 659.3))))*5232.85324);   
}
float noise(vec2 uv)
{
    vec2 i = floor(uv);
    vec2 f = fract(uv);
    f = f * f * (3. - 2. * f);

    float lb = hash(i + vec2(0., 0.));
    float rb = hash(i + vec2(1., 0.));
    float lt = hash(i + vec2(0., 1.));
    float rt = hash(i + vec2(1., 1.));

    return mix(mix(lb, rb, f.x), 
               mix(lt, rt, f.x), f.y);
}
