vec2 grad(vec2 uv){
float mid=tex(uv*iResolution.xy).r;
return vec2(tex(uv*iResolution.xy-vec2(0.5,0.0)).r-tex(uv*iResolution.xy+vec2(0.5,0.0)).r,tex(uv*iResolution.xy+vec2(0.0,-0.5)).r-tex(uv*iResolution.xy+vec2(0.0,0.5)).r)/(((mid+2.0)/4.0));
}
vec2 RK4(vec2 p){
    vec2 k1 = grad(p);
    vec2 k2 = grad((p-0.5*dt*k1));
    vec2 k3 = grad((p-0.5*dt*k2));
    vec2 k4 = grad((p-dt*k3));
    return dt/3.*(0.5*k1+k2+k3+0.5*k4);
}
